        /// <summary>按贴图名查尺寸记录。</summary>
        internal static bool TryGet(string spriteName, out Entry entry)
        {
            entry = default(Entry);
            return !string.IsNullOrEmpty(spriteName) && Table.TryGetValue(spriteName, out entry);
        }

        /// <summary>内容尺寸（皮肤归一应该对齐的目标）。</summary>
        internal static bool TryGetContentSize(string spriteName, out Vector2Int size)
        {
            size = default(Vector2Int);
            if (!TryGet(spriteName, out Entry entry)) return false;
            size = new Vector2Int(entry.ContentWidth, entry.ContentHeight);
            return true;
        }
